test('2. create → edit → deactivate round-trip', {
    annotation: {
      type: 'description',
      description: `Drives the full UI round-trip: create a complaint type at root tenant, edit its SLA from 24 to 72 hours through the form, and confirm the change persists. Skips if no active department exists on the tenant (prerequisite for the dept FK).

Steps:
1. test.skip if !liveDeptCode (beforeAll picks first active dept).
2. Generate a unique code + name; track for cleanup.
3. Navigate to /complaint-types/create; fill the name field (input[name="name"]; labelled "Complaint Subcategory", "Complaint Sub-Type" before #2243, "Name" before that), Service Code, pick Department option, set SLA=24.
4. Click Create; wait for navigation back to LIST_PATH.
5. Search for the code in the list; click the row to open detail.
6. Click Edit; set SLA to 72; click Save and wait for the MDMS _update response.
7. mdmsSearch at TENANT_CODE for [code]; assert data.slaHours === 72.

Cleanup is API-only — soft-deletes via cleanupMdms in afterAll because there's no UI delete affordance for complaint types.`,
    },
    tag: ['@area:configurator-manage', '@area:pgr', '@kind:regression', '@layer:ui', '@persona:admin'] }, async ({
    page,
  }, testInfo) => {
    if (!liveDeptCode) test.skip(true, 'No active department seeded on tenant');

    // PascalCase kind — DigitFormCodeInput strips non-alphanumerics when
    // deriving the code from the name.
    const code = testCode(testInfo, 'CT_RT');
    const name = `PW Roundtrip ${code}`;
    createdCodes.add(storedId(code));

    await page.goto(`${LIST_PATH}/create`);
    // Find the name field by its input name, which DigitFormInput takes from
    // `source="name"` and which no copy change touches. Its label was renamed
    // "Name" → "Complaint Sub-Type" → "Complaint Subcategory" (#2243); the
    // label match is only a fallback. Its id is React's useId, so not #name.
    await page.locator('input[name="name"]').or(page.getByLabel(/^Complaint (Sub-Type|Subcategory)/i)).first().fill(name);

    const codeInput = page.getByLabel(/Service Code/i);
    await codeInput.fill('');
    await codeInput.fill(code);

    // Department select — typeahead or click + pick first option matching
    // our scratch dept code.
    const deptSelect = page.getByLabel(/^Department/i);
    await deptSelect.click();
    const deptOption = page.getByRole('option', { name: new RegExp(liveDeptCode!, 'i') }).first();
    if (await deptOption.isVisible().catch(() => false)) {
      await deptOption.click();
    } else {
      // Fall back to first option.
      await page.getByRole('option').first().click();
    }

    await page.getByLabel(/SLA/i).fill('24');

    await Promise.all([
      page.waitForURL(LIST_PATH, { timeout: 30_000 }),
      page.getByRole('button', { name: /^Create$/ }).click(),
    ]);

    const auth = loadAuth();

    // --- Edit SLA ---
    await page.locator('#main-content').getByPlaceholder(/search/i).first().fill(code);
    await page.waitForLoadState('networkidle').catch(() => {});
    const row = page.getByRole('row').filter({ hasText: code });
    await expect(row).toBeVisible();
    await row.click();

    await page.getByRole('button', { name: /^Edit$/i }).click();
    const sla = page.getByLabel(/SLA/i);
    await sla.fill('72');
    // The click resolves when it is dispatched; search only after MDMS has the update.
    const saved = page.waitForResponse(
      (r) => r.request().method() === 'POST' && new URL(r.url()).pathname.includes('/_update'),
      { timeout: 30_000 },
    );
    await page.getByRole('button', { name: /^Save$/i }).click();
    expect((await saved).ok(), 'the configurator MDMS _update for the SLA edit').toBe(true);

    // --- Verify SLA persisted via MDMS ---
    const afterEdit = await mdmsSearch(auth, TENANT_CODE, SCHEMA, {
      uniqueIdentifiers: [storedId(code)],
      limit: 5,
    });
    expect(afterEdit.length).toBeGreaterThan(0);
