test('1 — acquire admin and citizen tokens', {
    annotation: {
      type: 'description',
      description: `Token-acquisition step of the API-only PGR lifecycle. Logs the configured ADMIN user in (root tenant) and registers a brand-new citizen via the OTP/registration helper using a freshly-generated phone — so the lifecycle has both ends of the request/resolve flow.

Steps:
1. Call getDigitToken with ROOT_TENANT, ADMIN_USER, ADMIN_PASS; assert the response contains an access_token.
2. Stash adminToken + adminUserInfo for later steps.
3. Call registerCitizen(CITIZEN_PHONE) which sends OTP, then either logs in or creates the citizen + retries login.
4. Assert the citizen response has a token; stash citizenToken + citizenUserInfo.

First link in a serial chain — every later step skips if this fails.`,
    },
    tag: ['@area:pgr', '@kind:lifecycle', '@layer:api', '@persona:cross'] }, async () => {
    const adminResp = await getDigitToken({
      tenant: ROOT_TENANT,
      username: ADMIN_USER,
      password: ADMIN_PASS,
    });
    expect(adminResp.access_token).toBeTruthy();
    adminToken = adminResp.access_token;
    adminUserInfo = adminResp.UserRequest as Record<string, unknown>;

    // GRO performs ASSIGN; PGR_LME performs RESOLVE. These employee personas
    // may live at the CITY tenant (e.g. EMP001 on mz.maputo), not the root
    // where ADMIN lives — so authenticate via getPrincipal, which probes
    // CITY→ROOT and returns null only when neither tenant accepts them.
    // The ACTOR only needs the GRO role — the department check does NOT apply
    // to it. ServiceRequestValidator.validateDepartment resolves departments
    // for request.getWorkflow().getAssignes(), i.e. the ASSIGNEE, so a bare-GRO
    // actor does not by itself produce 400 DEPARTMENT_NOT_FOUND. (An earlier
    // probe read it the other way round because actor and assignee were both
    // ADMIN; the actor=PGGRO1/assignee=ADMIN probe recorded below disambiguates
    // it.) The assignee guard is the `departmented(lme)` assertion further down.
    //
    // Still prefer the 'gro-with-department' persona: it is what the pg
    // expectations require, and on a seeded tenant it is the same employee that
    // must also be assignable. But do NOT hard-require it — a deployment with a
    // departmented LME and a bare-GRO ADMIN legitimately passes ASSIGN, so
    // falling back to GRO_USER keeps that case green rather than inventing a
    // failure the service would not raise.
    const groPersona = await resolvePersona('gro-with-department').catch(() => null);
    const gro = groPersona ?? (await getPrincipal(GRO_USER, GRO_PASS));
    expect(
      gro,
      `a GRO must log in (tried persona 'gro-with-department', then ${GRO_USER} on CITY + ROOT)`,
    ).toBeTruthy();
    groToken = gro!.token;
    groUserInfo = gro!.userInfo;

    // The ASSIGNEE must carry an HRMS department too — pgr-services rejects the
    // ASSIGN with 400 DEPARTMENT_NOT_FOUND naming the ASSIGNEE's uuid, not the
    // actor's. Probed both directions to be sure:
    //   actor=PGGRO1 (DEPT_3), assignee=PGGRO1 -> 200
    //   actor=PGGRO1 (DEPT_3), assignee=ADMIN  -> 400 DEPARTMENT_NOT_FOUND [ADMIN uuid]
    // EMPLOYEE_USER defaults to ADMIN, which holds PGR_LME but no department, so
    // the bare 'lme' persona is not sufficient to be assigned work.
    const lmePersona = await resolvePersona('lme').catch(() => null);
    const departmented = (p: { departments?: string[] } | null) => (p?.departments?.length ?? 0) > 0;
    // Fall back to the departmented GRO only when it can actually do the LME's
    // job (it must still hold PGR_LME to RESOLVE later in this chain).
    const lmeFallback = departmented(groPersona) && (groPersona?.roles ?? []).includes('PGR_LME')
      ? groPersona
      : null;
    const lme = departmented(lmePersona)
      ? lmePersona
      : (lmeFallback ?? (await getPrincipal(EMPLOYEE_USER, EMPLOYEE_PASS)));
    expect(
      lme,
      `an LME must log in (tried persona 'lme', a departmented GRO, then ${EMPLOYEE_USER})`,
    ).toBeTruthy();
    expect(
      departmented(lme as { departments?: string[] }),
      `the assignee must carry an HRMS department — pgr-services returns 400 ` +
        `DEPARTMENT_NOT_FOUND otherwise. Resolved '${(lme as { username?: string })?.username ?? EMPLOYEE_USER}' ` +
        `with departments=[${((lme as { departments?: string[] })?.departments ?? []).join(',') || 'none'}]. ` +
        `Point EMPLOYEE_USER at a departmented PGR_LME employee, or seed one.`,
    ).toBe(true);
    // ...and it must be able to do the LME's job. This same principal RESOLVEs
    // further down the chain, which pgr-services only permits for PGR_LME. The
    // 'lme' persona and the GRO fallback are both role-checked on the way in,
    // but the last-resort EMPLOYEE_USER login is not — without this, a
    // departmented non-LME reaches RESOLVE and fails there with an
    // authorisation error that reads like a workflow bug rather than a
    // misconfigured EMPLOYEE_USER.
    expect(
      (lme as { roles?: string[] })?.roles ?? [],
      `the assignee must also hold PGR_LME — it RESOLVEs later in this chain. ` +
        `Resolved '${(lme as { username?: string })?.username ?? EMPLOYEE_USER}' ` +
        `with roles=[${((lme as { roles?: string[] })?.roles ?? []).join(',') || 'none'}].`,
    ).toContain('PGR_LME');
    lmeToken = lme!.token;
    lmeUserInfo = lme!.userInfo;

    const citizenResp = await registerCitizen(CITIZEN_PHONE);
    expect(citizenResp.token).toBeTruthy();
    citizenToken = citizenResp.token;
    citizenUserInfo = citizenResp.userInfo;
    console.log(`Admin and citizen (${CITIZEN_PHONE}) tokens acquired`);
  })

test('all API calls carry JWT through proxy (no 401s after login)', {
    tag: ['@area:proxy', '@kind:regression', '@layer:api', '@persona:cross'],
  }, async ({ page }) => {
    const unauthorizedCalls: string[] = [];
    const authedApiCalls: string[] = [];

    page.on('response', (resp) => {
      const url = resp.url();
      if (!url.includes(BASE_URL.replace('https://', '').replace('http://', ''))) return;
      if (url.includes('/digit-ui/') || url.includes('/auth/login')) return;
      if (url.includes('unpkg') || url.includes('fonts') || url.includes('s3.ap')) return;
      // KC SSO iframe calls are expected to return 403
      if (url.includes('/realms/') && url.includes('iframe')) return;
      if (url.includes('/3p-cookies/')) return;

      const path = url.replace(BASE_URL, '').split('?')[0];
      authedApiCalls.push(`${resp.request().method()} ${path}`);
      if (resp.status() === 401) {
        unauthorizedCalls.push(`${resp.request().method()} ${path}`);
      }
    });

    // Login via token injection (portable — see the note in the first test).
    await loginViaApi(page, { tenant: TENANT, username: ADMIN_USER, password: ADMIN_PASS });
    await page.waitForTimeout(3000);

    // Navigate through pages
    await page.goto(`${BASE_URL}/${tenantSlug()}/digit-ui/employee/pgr/inbox-v2`, {
      waitUntil: 'networkidle',
      timeout: 30_000,
    });
    await page.waitForTimeout(3000);

    // Presence guard FIRST — without it this test is an absence assertion over a
    // possibly-empty set. If loginViaApi injected a token the SPA never used, or the
    // page failed to boot, zero calls would be recorded and `[] === []` would pass
    // while nothing was exercised. Its sibling above already asserts
    // `mdmsCalls.length >= 1`; this one did not.
    expect(
      authedApiCalls.length,
      'no authenticated API calls were observed — the 401 check would be vacuous',
    ).toBeGreaterThan(0);

    // No API call after login should return 401
    expect(unauthorizedCalls).toEqual([]);
  })

test('MDMS, localization, and access APIs work with JWT auth', {
    tag: ['@area:proxy', '@kind:regression', '@layer:api', '@persona:cross'],
  }, async ({ page }) => {
    // Navigate to the domain first so fetch calls are same-origin. Not to a
    // digit-ui page: with the BFF session in auth-api.json the SPA runs its own
    // context _select and redirects, and that navigation aborts the fetches below.
    await page.goto(`${BASE_URL}/identity/v1/tenant-contexts/${tenantSlug()}`, { waitUntil: 'domcontentloaded', timeout: 30_000 });

    // Acquire a token through hosted sign-in + the BFF context exchange
    // (getDigitToken). This test is about proxy coverage of the downstream
    // service APIs, not the auth mechanism.
    const loginResp = await getDigitToken({ tenant: ROOT_TENANT, username: ADMIN_USER, password: ADMIN_PASS });
    expect(loginResp.access_token).toBeTruthy();
    const token = loginResp.access_token;

    // A real RequestInfo, not a bare `{apiId}`. Several DIGIT services dereference
    // these without a null check and answer an unhandled NullPointerException as a
    // 400 — pgr-services needs `userInfo` (`RequestInfo.getUserInfo().getType()`)
    // and egov-accesscontrol needs `ts` (`RequestInfo.getTs().longValue()`). With a
    // stub RequestInfo four of the seven endpoints below 400, which the old
    // `toBeLessThan(500)` assertion happily called "work with JWT auth".
    expect(
      loginResp.UserRequest,
      'token response should carry UserRequest to build a real RequestInfo',
    ).toBeTruthy();
    const requestInfo = {
      apiId: 'Rainmaker',
      ver: '.01',
      ts: 0,
      action: '_search',
      did: '1',
      key: '',
      msgId: 'proxy-coverage|en_IN',
      authToken: token,
      userInfo: loginResp.UserRequest,
    };

    // Test each critical API endpoint
    const endpoints = [
      {
        name: 'MDMS search',
        url: `${BASE_URL}/mdms-v2/v1/_search`,
        body: {
          RequestInfo: requestInfo,
          MdmsCriteria: {
            tenantId: ROOT_TENANT,
            moduleDetails: [{ moduleName: 'tenant', masterDetails: [{ name: 'tenants' }] }],
          },
        },
      },
      {
        // locale/tenantId/module are QUERY params on this service — sent in the
        // body they are simply absent and it 400s "Required request parameter
        // 'locale' ... is not present". Locale comes from the profile, not a literal.
        name: 'Localization search',
        url: `${BASE_URL}/localization/messages/v1/_search?tenantId=${ROOT_TENANT}&locale=${LOCALES[0]}&module=rainmaker-common`,
        body: { RequestInfo: requestInfo },
      },
      {
        // Needs tenantId + roleCodes (not `rolesCodes`, and not objects) — the old
        // shape 400d with "Tenant Id is required" + "Atleast One Role is Required".
        name: 'Access control',
        url: `${BASE_URL}/access/v1/actions/mdms/_get`,
        body: {
          RequestInfo: requestInfo,
          tenantId: ROOT_TENANT,
          roleCodes: ['EMPLOYEE'],
          actionMaster: 'actions-test',
          enabled: true,
        },
      },
      {
        name: 'PGR search',
        url: `${BASE_URL}/pgr-services/v2/request/_search?tenantId=${TENANT}`,
        body: { RequestInfo: requestInfo },
      },
      {
        name: 'Boundary search',
        url: `${BASE_URL}/boundary-service/boundary-relationships/_search?tenantId=${TENANT}&hierarchyType=${tryGetProfile()?.boundary.hierarchyType || 'ADMIN'}`,
        body: { RequestInfo: requestInfo },
      },
      {
        // tenantId is a QUERY param here too — in `criteria` it never arrives.
        name: 'HRMS employee count',
        url: `${BASE_URL}/egov-hrms/employees/_count?tenantId=${TENANT}`,
        body: { RequestInfo: requestInfo },
      },
      {
        name: 'Workflow business service',
        url: `${BASE_URL}/egov-workflow-v2/egov-wf/businessservice/_search?tenantId=${TENANT}&businessServices=PGR`,
        body: { RequestInfo: requestInfo },
      },
    ];

    for (const endpoint of endpoints) {
      const result = await page.evaluate(
        async ({ url, body, token }) => {
          const resp = await fetch(url, {
            method: 'POST',
            headers: {
              Authorization: `Bearer ${token}`,
              'Content-Type': 'application/json',
            },
            body: JSON.stringify(body),
          });
          return { status: resp.status, ok: resp.ok, body: (await resp.text()).slice(0, 300) };
        },
        { url: endpoint.url, body: endpoint.body, token },
      );

      // The endpoint must actually WORK, which is what this test's name claims.
      //
      // The previous assertion was `toBeLessThan(500)`, which cannot fail for any
      // reachable endpoint: a 400, a 401, even a 404 from a service that does not
      // exist all satisfy it. Four of the seven endpoints here were 400ing — one
      // with a server-side NullPointerException — under a green test. Verified:
      // pointing a URL at `/pgr-servicesXXX/...` returns 404, and 404 < 500, so the
      // old form stayed green even against a service that isn't there.
      expect(
        result.ok,
        `${endpoint.name} returned ${result.status}: ${result.body}`,
      ).toBe(true);
    }
  })

