test('hosted sign-in + chrome + visible decrypt + inbox honest drives', {
    annotation: {
      type: 'description',
      description: `One pass through the employee app's sign-in and shell, covering #592, #505, #622, #344 and #432.

Steps:
1. A complaint assigned to an employee exists (lifecycle setup, or ASSIGNED_COMPLAINT_ID).
2. #592: /digit-ui/globalConfigs.js is served and names the state tenant.
3. #505 sub-1: the hosted sign-in page renders its brand banner, not white.
4. #505 sub-3: the sign-in header logo renders and loads. The page takes it from MDMS common-masters.StateInfo (logoUrl / logoUrlWhite); when both are empty it shows the workspace name instead, and this step fails saying so.
5. #622: signing in completes and the employee shell mounts (no 503 / "Something went wrong").
6. #505 sub-2: the header shows the signed-in user's initial.
7. #505 sub-4: dropdown icons render dark, not white-on-white.
8. #344: the assigned complaint's details show the citizen's name and mobile decrypted, not as hex.
9. #432: the inbox mounts, every row is in an open workflow state, the status filter is populated, and only the sortable column has a sort icon.`,
    },
    tag: ['@persona:employee'],
  }, async ({ page }) => {
    // This test used to carry an unconditional `test.fixme(true, …)` blaming
    // two onboarding-data gaps. Both claims were false and are now retired:
    //   * "#344 needs a seeded ASSIGNED_COMPLAINT_ID" — lifecycle.setup.ts DOES
    //     seed one (lifecycle-fixtures.json -> complaints.assigned_to_employee),
    //     which is exactly what the resolution chain above reads.
    //   * "#505 brand chrome needs tenant branding onboarded" — the sign-in
    //     banner renders its brand colour from the shipped stylesheet with zero
    //     branding seeded.
    //
    // No skip guard here on purpose: an unresolved SRID is a broken
    // lifecycle-setup, not a legitimate "nothing to test" — fail loudly with the
    // cause rather than driving the UI at a blank SRID and timing out opaquely.
    expect(
      ASSIGNED_COMPLAINT_ID,
      'no assigned_to_employee complaint available — lifecycle.setup.ts did not seed one; set ASSIGNED_COMPLAINT_ID to override',
    ).not.toBe('');

    // ============ #592 globalConfigs.js ============
    const gcResp = await page.request.get(`${BASE_URL}${GLOBAL_CONFIGS_URL}?cb=${Date.now()}`);
    expect(gcResp.status()).toBe(200);
    expect(await gcResp.text()).toMatch(/STATE_LEVEL_TENANT_ID|stateTenantId/);

    // ============ #505 sub-1 + sub-3 — hosted sign-in page (Keycloak theme) ============
    // Since #1999 the employee signs in on Keycloak's digit-employee theme
    // (keycloak/theme-src EmployeeTemplate.tsx); the digit-ui form with its
    // .banner / City picker is gone. Without carousel images the card sits on
    // .dg-banner (--color-digitv2-header-sidenav), with them on .dg-carousel-shell.
    // The sign-in theme fetches its branding (MDMS common-masters.StateInfo,
    // which holds the logo URLs) while it loads; keep it to explain a missing logo.
    const brandingResp = page
      .waitForResponse(
        (r) => r.url().includes('/identity/v1/branding-api/mdms-v2/') && r.request().method() === 'POST',
        { timeout: 30_000 },
      )
      .catch(() => null);
    await page.goto(authorizeUrl(BASE_URL, 'employee'));
    await expect(page.locator('#username')).toBeVisible({ timeout: 30_000 });
    const shell = page.locator('.dg-root.dg-employee').locator('.dg-banner, .dg-carousel-shell').first();
    await expect(shell, '#505 — the digit-employee theme must render its sign-in shell').toBeVisible();
    if (await page.locator('.dg-banner').count()) {
      const bannerBg = await page.locator('.dg-banner').first().evaluate((el) => getComputedStyle(el).backgroundColor);
      expect(bannerBg, '#505 sub-1 — sign-in banner must render with a brand color, not white').not.toMatch(
        /rgba?\(\s*255\s*,\s*255\s*,\s*255/,
      );
    }

    /*
     * #505 sub-3: TenantHeader's logo (Chrome.tsx). SafeImage renders nothing
     * for an unset or failed src, so a broken logo shows up here as a missing
     * element; naturalWidth guards against a decoded-but-empty box too. The
     * stylesheet pins height 56px; 20px is the collapse floor, not a size pin.
     */
    const stateInfo = await brandingResp
      .then(async (r) => {
        const body = (await r?.json().catch(() => null)) as
          | { MdmsRes?: { 'common-masters'?: { StateInfo?: Array<{ logoUrl?: string; logoUrlWhite?: string }> } } }
          | null;
        return body?.MdmsRes?.['common-masters']?.StateInfo?.[0] ?? null;
      })
      .catch(() => null);
    const logoNotConfigured = !!stateInfo && !stateInfo.logoUrl && !stateInfo.logoUrlWhite;
    const logo = page.locator('.dg-banner-header__logo').first();
    await expect(
      logo,
      '#505 sub-3 — the sign-in header logo must render.' +
        (logoNotConfigured
          ? ' It comes from MDMS common-masters.StateInfo.logoUrl (logoUrlWhite on the dark banner), which is empty ' +
            'for this workspace, so the page shows the workspace name instead.'
          : ''),
    ).toBeVisible();
    // The CSS gives the <img> its box before the request lands: wait for the decode.
    await expect
      .poll(() => logo.evaluate((img: HTMLImageElement) => img.complete && img.naturalWidth > 0), {
        message: '#505 sub-3 — logo image must actually load',
        timeout: 15_000,
      })
      .toBe(true);
    const logoBox = await logo.evaluate((img: HTMLImageElement) => ({
      w: img.offsetWidth, h: img.offsetHeight, natW: img.naturalWidth, natH: img.naturalHeight,
    }));
    expect(logoBox.natW, '#505 sub-3 — logo image must actually load').toBeGreaterThan(0);
    expect(logoBox.natH, '#505 sub-3 — logo image must actually load').toBeGreaterThan(0);
    expect(logoBox.w, '#505 sub-3 logo laid-out width').toBeGreaterThanOrEqual(20);
    expect(logoBox.h, '#505 sub-3 logo laid-out height').toBeGreaterThanOrEqual(20);

    // ============ #622 — sign-in completes and the shell mounts ============
    // The persona signs in without the page (loginViaApi), so its password is
    // never typed into a traced browser; the hosted form above is only looked at.
    await loginViaApi(page, { tenant: TENANT, username: EMPLOYEE_USER, password: EMPLOYEE_PASS });
    await page.waitForURL(/\/digit-ui\/employee(?!\/user\/login)/, { timeout: 30_000 });
    await page.waitForTimeout(3_000);

    // ============ #505 sub-2 — header initial visible ============
    /*
     * The header renders the initial of the user's DISPLAY NAME, not of their
     * username: TopBar.js passes `userDetails.info.name` to the Dropdown's
     * `profilePic` prop, and Dropdown renders a string prop as
     * `profilePic[0].toUpperCase()`. The expectation comes from egov-user's
     * own record, not from the session the header reads: if the context
     * exchange put the username in info.name, both would agree on the wrong
     * initial.
     */
    const session = await page.evaluate(() => {
      const user = (window as any).Digit?.UserService?.getUser?.();
      return { token: user?.access_token as string, uuid: user?.info?.uuid as string, tenantId: user?.info?.tenantId as string };
    });
    const userSearch = await page.request.post(`${BASE_URL}/user/_search`, {
      data: { RequestInfo: { authToken: session.token }, tenantId: session.tenantId || TENANT, uuid: [session.uuid] },
    });
    expect(userSearch.status(), '#505 sub-2 — egov-user must return the signed-in employee').toBe(200);
    const displayName = String((await userSearch.json()).user?.[0]?.name ?? '').trim();
    expect(
      displayName,
      `#505 sub-2 — no display name in the session for ${EMPLOYEE_USER}; the header initial has no expectation to compare against`,
    ).not.toBe('');
    const expectedInitial = displayName.charAt(0).toUpperCase();
    const headerInitial = await page.evaluate((expected) => {
      const headerNodes = [
        ...document.querySelectorAll(
          'header *, [class*="topbar" i] *, [class*="TopBar" i] *, [class*="header" i] *',
        ),
      ];
      return headerNodes.find((n) => (n.textContent || '').trim() === expected) ? true : false;
    }, expectedInitial);
    expect(headerInitial, `#505 sub-2 — header must surface user initial '${expectedInitial}'`).toBe(
      true,
    );

    // ============ #505 sub-4 — dropdown icons rendered with dark fill ============
    const profileTrigger = page.locator('.header-dropdown-profile').first();
    if (await profileTrigger.isVisible().catch(() => false)) {
      await profileTrigger.scrollIntoViewIfNeeded();
      const btn = profileTrigger.locator('xpath=ancestor::button[1]');
      if (await btn.isVisible().catch(() => false)) await btn.click();
      else await profileTrigger.click();
      await page.waitForTimeout(1_500);

      await expect(page.getByText(/Edit Profile/i).first()).toBeVisible({ timeout: 8_000 });
      await expect(page.getByText(/Logout/i).first()).toBeVisible({ timeout: 8_000 });

      const iconColors = await page.evaluate(() => {
        const items = [...document.querySelectorAll('.header-dropdown-option, [role="menuitem"]')];
        const colors: string[] = [];
        for (const item of items) {
          const svg = item.querySelector('svg path, svg rect, svg circle') as SVGElement | null;
          if (svg) {
            const fill = svg.getAttribute('fill') || getComputedStyle(svg).fill;
            if (fill) colors.push(fill);
          }
        }
        return colors;
      });
      const hasDark = iconColors.some(
        (c) =>
          !/^#?fff(fff)?$/i.test(c.trim()) &&
          !/^rgb\(\s*255\s*,\s*255\s*,\s*255\s*\)$/.test(c.trim()) &&
          !/^rgba?\(\s*255\s*,\s*255\s*,\s*255/.test(c.trim()),
      );
      expect(hasDark, `#505 sub-4 — at least one dropdown icon must be visibly dark`).toBeTruthy();
      await page.keyboard.press('Escape');
      await page.waitForTimeout(800);
    }

    // ============ #344 — complaint detail visible decrypt ============
    await page.goto(
      `${BASE_URL}/${tenantSlug()}/digit-ui/employee/pgr/complaint-details/${ASSIGNED_COMPLAINT_ID}?cb=${Date.now()}`,
    );
    await page.waitForLoadState('domcontentloaded');
    await page.waitForTimeout(4_500);

    const detailBody = (await page.locator('body').innerText()) || '';
    expect(detailBody, '#344 — detail body must not surface base64-shaped hex blobs').not.toMatch(
      /\b[A-Za-z0-9+/]{30,}=+/,
    );
    await expect(
      page.getByText(/Contact Details:\s*\d{9,10}/).first(),
      '#344 — Contact Details must render decrypted (numeric)',
    ).toBeVisible({ timeout: 15_000 });

    // ============ #432 sub-1/2/3 — inbox honest drives ============
    await page.goto(`${BASE_URL}${surfacePath('employee', 'pgr/inbox-v2')}?cb=${Date.now()}`);
    await page.waitForLoadState('domcontentloaded');
    await page.waitForTimeout(4_000);

    await expect(page.getByText(/service unavailable|503|something went wrong/i)).toHaveCount(0);
    await expect(page.locator('table, [role="table"]').first()).toBeVisible({ timeout: 20_000 });

    const body = (await page.locator('body').innerText()) || '';
    expect(body, '#432/#344 — inbox body must not surface base64-shaped hex blobs').not.toMatch(
      /\b[A-Za-z0-9+/]{30,}=+/,
    );

    // sub-1: rows in OPEN states only
    const OPEN_STATES = /PENDINGFORASSIGNMENT|PENDINGFORREASSIGNMENT|PENDINGATLME|PENDINGFORWORK|OPEN/i;
    const CLOSED_STATES = /RESOLVED|REJECTED|CLOSED/i;
    const rowCount = await page.locator('tbody tr').count();
    if (rowCount > 0) {
      const rowsText = await page.locator('tbody tr').allInnerTexts();
      const offenders = rowsText
        .filter((r) => OPEN_STATES.test(r) || CLOSED_STATES.test(r))
        .filter((r) => CLOSED_STATES.test(r) && !OPEN_STATES.test(r));
      expect(offenders.length, `#432 sub-1 — inbox default view should only surface OPEN states`).toBe(0);
    }

    // sub-2: status filter dropdown populated
    const statusFilterTrigger = page
      .locator('button, [role="combobox"], [class*="filter" i]')
      .filter({ hasText: /status|workflow/i })
      .first();
    if (await statusFilterTrigger.isVisible({ timeout: 5_000 }).catch(() => false)) {
      await statusFilterTrigger.click();
      await page.waitForTimeout(1_500);
      const filterOptions = page.locator(
        '[role="listbox"][data-state="open"] [role="option"], [role="option"], [class*="filter" i] input[type="checkbox"]',
      );
      expect(
        await filterOptions.count(),
        '#432 sub-2 — status filter must list at least 1 option',
      ).toBeGreaterThan(0);
      await page.keyboard.press('Escape');
      await page.waitForTimeout(700);
    }

    // sub-3: only sortable column has a sort icon
    const headerCells = page.locator('thead th, thead [role="columnheader"]');
    const headerCount = await headerCells.count();
    if (headerCount > 0) {
      let sortableCount = 0;
      for (let i = 0; i < headerCount; i++) {
        const html = (await headerCells.nth(i).innerHTML().catch(() => '')) || '';
        if (/<svg|class="[^"]*sort|aria-sort/i.test(html)) sortableCount++;
      }
      expect(
        sortableCount,
        `#432 sub-3 — only the sortable column should show a sort icon; got ${sortableCount}/${headerCount}`,
      ).toBeLessThanOrEqual(1);
    }
  })

test('PENDINGATLME → Escalate → real ESCALATE transition into the configured target state', { tag: ['@persona:employee'] }, async ({ page }) => {
    requires(test, CAPABILITY, 'employee #521 escalate');
    test.skip(!!seedSkipReason, seedSkipReason);
    test.skip(!COMPLAINT_ID, 'no complaint at PENDINGATLME available (seed produced no id)');

    // Whoever logs in here just needs the PGR_LME role, not to literally be
    // the complaint's assignee: egov-workflow-v2's nextActions is computed
    // from the CALLER's own roles against the businessService state config
    // (the same fact seed.ts's driveToResolved leans on — "RESOLVE is
    // role-gated, not assignee-gated"). That sidesteps the EMPLOYEE_USER
    // env var entirely, which on bomet defaults to ADMIN and does not carry
    // PGR_LME (see personas.ts's persona-triple comment: HS_GRO has GRO but
    // not PGR_LME; DEMO_WATER has PGR_LME but no login is known for it).
    // getPersona('lme') discovers a credentialed PGR_LME holder instead.
    const lme = await getPersona('lme');
    const reader: Principal | null = await getPrincipal(lme.username, lme.password);
    expect(reader, `could not acquire a token for the LME persona ${lme.username}`).not.toBeNull();

    // ============ What THIS deployment wires ESCALATE to ============
    const escalateTarget = await escalateTargetFromPendingAtLme(lme.token);
    expect(
      escalateTarget,
      '#521 — the PGR businessService must define an active ESCALATE action on PENDINGATLME ' +
        `(the app seeds it as PENDINGATLME --ESCALATE--> ${SEEDED_ESCALATE_TARGET})`,
    ).not.toBeNull();
    expect(escalateTarget, 'ESCALATE must be a PENDINGATLME self-loop').toBe(SEEDED_ESCALATE_TARGET);

    // ============ digit-ui employee login ============
    // Token injection, not the login form: the login page's city picker is a
    // custom select with no <label> and no accessible name, so driving it by
    // role/name hangs until the test times out. Every other employee UI spec
    // (workflow-lifecycle-ui, inbox-filters, inbox-search, …) logs in this way.
    const loggedIn = await loginEmployeeBrowser(page, lme.username, lme.password);
    expect(loggedIn, `digit-ui login failed for the LME persona ${lme.username}`).toBeTruthy();

    // ============ Open the assigned complaint detail ============
    await page.goto(
      `${BASE_URL}/${tenantSlug()}/digit-ui/employee/pgr/complaint-details/${COMPLAINT_ID}`,
      { waitUntil: 'domcontentloaded', timeout: 30_000 },
    );
    await page.locator('.digit-viewcard-field-pair, .v2-pgr-details').first()
      .waitFor({ state: 'visible', timeout: 30_000 });
    await page.waitForTimeout(3_000);

    // Precondition, stated rather than assumed: the seed really is at PENDINGATLME.
    expect(await apiStatus(reader!, COMPLAINT_ID)).toBe('PENDINGATLME');

    // ============ Take action → Escalate ============
    const takeActionBtn = page.locator('.digit-action-bar-wrap button, .action-bar-wrap button, footer button').first();
    await expect(takeActionBtn).toBeVisible({ timeout: 15_000 });
    await takeActionBtn.click();
    await page.waitForTimeout(1_500);

    const escalateOption = page.getByText(/^Escalate$/i).first();
    await expect(
      escalateOption,
      '#521 — Escalate option must appear in the Take action menu when state = PENDINGATLME',
    ).toBeVisible({ timeout: 8_000 });
    await escalateOption.click();
    await page.waitForTimeout(2_000);

    // ============ Fill comment + submit ============
    // The comment box IS the #521 regression guard: before the ACTION_CONFIGS
    // fix, getUpdatedConfig() returned null for ESCALATE and PGRWorkflowModal
    // short-circuited to an empty modal with no form at all.
    const comment = `UI-ESCALATE ${Date.now()}`;
    const commentBox = page.locator('textarea').first();
    await expect(
      commentBox,
      '#521 — Escalate must render its comment form, not an empty no-op modal',
    ).toBeVisible({ timeout: 10_000 });
    await commentBox.fill(comment);

    await expect(page.getByText(/employee name/i)).toHaveCount(0);
    await page.getByRole('button', { name: /^SUBMIT$|^Submit$/ }).first().click();

    // ============ Verify a real ESCALATE transition happened ============
    // This is the load-bearing assertion. Where a self-loop is configured the
    // applicationStatus check below is trivially satisfied even by a no-op
    // submit, so the proof that anything happened is a fresh ESCALATE process
    // instance carrying the comment we just typed.
    await expect
