    await expect(page.getByText(/Assign Complaint|CS_ACTION_ASSIGN/i).first()).toBeVisible({ timeout: 10_000 });

    // Pick the (first) LME assignee from the department-grouped picker.
    const empInput = page.locator('.digit-dropdown-employee-select-wrap input[type="text"]').first();
    await empInput.click();
    await page.waitForTimeout(800);
    // NOTE (2026-08-10): this currently fails on a tenant that has any DEACTIVATED
    // employee, and the failure is an APP DEFECT, not a test bug — left red on
    // purpose so it keeps reporting.
    //
    // admin/employees "5. deactivate" leaves PW_* employees with
    // eg_hrms_employee.active=false AND eg_user.active=false. The Take-Action
    // ASSIGN dropdown still OFFERS them; picking one makes PGR reject the assign:
    //     400 INVALID UUID "User not found for uuid: b8981ea2-..."
    //     (= PW_D645324A_EMPROLE, inactive in both tables)
    // so the complaint stays PENDINGFORASSIGNMENT and this poll times out.
    // The dropdown must exclude inactive employees. Any real operator hits this
    // the moment their tenant has ever deactivated staff.
    //
    // Deliberately NOT worked around here: employee display names are encrypted
    // at rest (eg_user.name is ciphertext), so the test cannot filter options by
    // text without decrypting, and picking "some other option" would hide a
    // defect that affects real users.
    const empOption = page.locator('.main-option').first();
    if (await empOption.count()) await empOption.click();
    else { await empInput.press('ArrowDown'); await empInput.press('Enter'); }
    await page.waitForTimeout(500);

    await page.locator('textarea').first().fill(assignComment);
    await page.getByRole('button', { name: /^SUBMIT$|^Submit$/ }).first().click();

    await expect.poll(async () => apiStatus(reader!, srid), { timeout: 25_000, intervals: [1500] })
      .toBe('PENDINGATLME');

    // Comment on the timeline.
    await page.reload({ waitUntil: 'domcontentloaded' });
    await page.waitForTimeout(3_000);
    expect(await timelineText(page)).toContain(assignComment);
    await page.context().close();

    // ---------- 2. RESOLVE as LME (fresh session) ----------
    page = await openDetailsAs(browser, lmeUser, lmePass);
    await takeAction(page, /^resolve$/i);
    await expect(page.getByText(/PGR_ACTION_RESOLVE|Resolve Complaint|Resolve/i).first()).toBeVisible({ timeout: 10_000 });
    await page.locator('textarea').first().fill(resolveComment);
    await page.getByRole('button', { name: /^SUBMIT$|^Submit$/ }).first().click();

    await expect.poll(async () => apiStatus(reader!, srid), { timeout: 25_000, intervals: [1500] })
      .toBe('RESOLVED');

    await page.reload({ waitUntil: 'domcontentloaded' });
    await page.waitForTimeout(3_000);
    expect(await timelineText(page)).toContain(resolveComment);
    await page.context().close();
  })

test('REJECT (GRO) with a rejection reason → REJECTED, reason on timeline @p0', { tag: ['@persona:employee'] }, async ({ page }) => {
    test.skip(!!setupSkip, setupSkip);
    test.skip(!reasonCodes.length, 'no RAINMAKER-PGR.RejectionReasons seeded on this deployment');

    const rejectComment = `UI-REJECT ${Date.now()}`;

    const ok = await loginEmployeeBrowser(page, actorUser, actorPass);
    test.skip(!ok, `login failed for ${actorUser}`);
    await page.goto(`${BASE_URL}/${tenantSlug()}/digit-ui/employee/pgr/complaint-details/${srid}`, { waitUntil: 'domcontentloaded', timeout: 30_000 });
    await page.locator('.digit-viewcard-field-pair, .v2-pgr-details').first().waitFor({ state: 'visible', timeout: 30_000 });
    await page.waitForTimeout(3_000);
    expect(await apiStatus(reader!, srid)).toBe('PENDINGFORASSIGNMENT');

    await takeAction(page, /^reject$/i);
    await expect(page.getByText(/PGR_ACTION_REJECT|Reject Complaint|Reject/i).first()).toBeVisible({ timeout: 10_000 });

    // Pick the first seeded rejection reason, remembering the label the operator
    // actually saw — that (not the MDMS code) is what the timeline renders once
    // CS_REJECTION__<CODE> is localized.
    const reasonInput = page.locator('.digit-dropdown-employee-select-wrap input[type="text"]').first();
    await reasonInput.click();
    await page.waitForTimeout(800);
    const firstReason = page.locator('.digit-dropdown-options-card .digit-dropdown-item').first();
    expect(await firstReason.count(), 'reject modal offers a rejection-reason option').toBeGreaterThan(0);
    const reasonLabel = (await firstReason.innerText()).trim();
    expect(reasonLabel.length, 'the picked reason has a visible label').toBeGreaterThan(0);
    await firstReason.click();
    await page.waitForTimeout(400);

    await page.locator('textarea').first().fill(rejectComment);
    await page.getByRole('button', { name: /^SUBMIT$|^Submit$/ }).first().click();

    await expect.poll(async () => apiStatus(reader!, srid), { timeout: 25_000, intervals: [1500] })
      .toBe('REJECTED');

    // The audit record itself carries the composed "[<CODE>] <free text>" — the
    // whole point of plumbing the picker into the workflow comment.
    const auditComment = await fetchRejectComment(reader!.token, srid);
    expect(auditComment, 'REJECT audit comment is "[<CODE>] <free text>"')
      .toMatch(/^\[[A-Z_][A-Z0-9_]*\]\s/);
    const auditCode = auditComment.match(/^\[([A-Z_][A-Z0-9_]*)\]/)![1];
    expect(reasonCodes, 'the recorded code is a seeded RejectionReasons entry').toContain(auditCode);
    expect(auditComment, 'free text preserved after the code').toContain(rejectComment);

    // Reason + comment render on the timeline. The UI resolves the code through
    // CS_REJECTION__<CODE>, so accept the localized reason label the operator
    // picked OR the raw bracketed code on a deployment where that key is
    // unlocalized (both are the same fact, differently rendered).
    await page.reload({ waitUntil: 'domcontentloaded' });
    await page.waitForTimeout(3_000);
    await expect(page.getByText(/Complaint Timeline|CS_COMPLAINT_DETAILS_COMPLAINT_TIMELINE/i).first()).toBeVisible({ timeout: 10_000 });
    const body = await page.locator('body').innerText();
    expect(body, 'free-text comment on timeline').toContain(rejectComment);
    expect(
      body.includes(reasonLabel) || body.includes(`[${auditCode}]`),
      `rejection reason on timeline (expected "${reasonLabel}" or "[${auditCode}]")`,
    ).toBeTruthy();
  })

test('jurisdiction shows the boundary name, not its code, on the employee home page', {
    annotation: {
      type: 'description',
      description: `Catches CCRS#2643: the working-context panel listed jurisdictions by raw boundary code (it looked up ADMIN_<CODE>, which nothing writes), and only showed names after the PGR module had loaded the boundary pack.

Steps:
1. Take the ward-scoped CSR persona (an onboarded employee holding a boundary jurisdiction in the PGR hierarchy) and read that boundary's localized name from rainmaker-boundary-<hierarchy> in the deployment's own store. The name must differ from the code, otherwise the assertion below could not tell them apart.
2. Sign in and land on the employee HOME page (not a complaint page), so the boundary pack has not been loaded by PGR.
3. Open the working-context box.
4. Assert a Jurisdiction chip contains the localized name and no chip is the bare code.`,
    },
    tag: ['@ccrs:2643', '@kind:regression', '@layer:ui', '@persona:employee'] }, async ({ page }) => {
    requires(test, 'personas.ward-scoped-csr');

    const hierarchy = getProfile().boundary.hierarchyType;
    expect(hierarchy, 'deployment profile must name the boundary hierarchy').toBeTruthy();
    const csr = await getPersona('ward-scoped-csr');
    expect(csr.jurisdictions.length, `persona ${csr.username} must hold a jurisdiction`).toBeGreaterThan(0);

    await loginViaApi(page, { tenant: TENANT, authTenant: csr.tenant, username: csr.username, password: csr.password });
    const locale = (await page.evaluate(() => localStorage.getItem('Employee.locale'))) || 'en_IN';

    // Pick the persona jurisdiction that has a distinct localized name.
    let code: string | undefined;
    let name: string | undefined;
    for (const c of csr.jurisdictions) {
      const n = await boundaryName(c, hierarchy!, locale);
      if (n && n !== c) {
        code = c;
        name = n;
        break;
      }
    }
    expect(
      name,
      `rainmaker-boundary-${hierarchy!.toLowerCase()} must hold a name different from the code for one of ${JSON.stringify(csr.jurisdictions)} (bare-code keys, #1002) — without it this spec cannot tell a name from a code`,
    ).toBeTruthy();

    // Home page, fresh load: the boundary pack is not there unless the box loads it.
    await page.goto(`${BASE_URL}${employeeHome()}`, { waitUntil: 'domcontentloaded', timeout: 30_000 });
    expect(new URL(page.url()).pathname, 'must be on the employee home, not a PGR page').not.toMatch(/pgr|complaint/i);

    await page.locator('.digit-working-context-trigger').first().click({ timeout: 30_000 });
    const panel = page.locator('.digit-working-context-panel');
    await expect(panel, 'working-context panel must open').toBeVisible({ timeout: 10_000 });

    const chips = panel.locator('.digit-working-context-chip');
    await expect(
      chips.filter({ hasText: name! }),
      `CCRS#2643 — jurisdiction ${code} must render as its localized name "${name}"`,
    ).not.toHaveCount(0, { timeout: 15_000 });
    // The type suffix "(Ward)" may follow the name; a chip that is just the code is the bug.
    await expect(
      chips.filter({ hasText: new RegExp(`^\\s*${code!.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}(\\s*\\(.*\\))?\\s*$`) }),
      `CCRS#2643 — no jurisdiction chip may show the bare code ${code}`,
    ).toHaveCount(0);
  })

